/* EUROMASTER Masternet Custom Widget — Regionaltagung 2027, v1.0.0 */
(() => {
  'use strict';
  const key = 'em-regionaltagung-2027-v1';
  const overlayId = 'em-regionaltagung-overlay';
  // Embedded Montserrat: no external font requests.
  [new FontFace('EM Montserrat', 'url(data:font/woff;base64,)', {weight: '400', display: 'swap'}),new FontFace('EM Montserrat', 'url(data:font/woff;base64,)', {weight: '800', display: 'swap'})].forEach(font => { document.fonts.add(font); font.load().catch(() => {}); });
  function mount() {
    try { if (sessionStorage.getItem(key)) return; } catch (_) {}
    if (document.getElementById(overlayId)) return;
    const previousFocus = document.activeElement;
    const host = document.createElement('div');
    host.id = overlayId;
    const root = host.attachShadow({mode: 'open'});
    root.innerHTML = `
      <style>
        :host{position:fixed;inset:0;z-index:2147483647;display:block;font-family:'EM Montserrat',Montserrat,Arial,sans-serif}
        *{box-sizing:border-box}
        .backdrop{position:absolute;inset:0;background:rgba(8,24,53,.68);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;padding:20px}
        .card{position:relative;width:100%;max-width:660px;max-height:calc(100dvh - 40px);overflow:auto;background:white;border-radius:22px;box-shadow:0 28px 80px #0005;color:#23324b}
        .heading{padding:30px 64px 25px 34px;background:linear-gradient(135deg,#144c9f,#0c7ac5);color:white;border-top:7px solid transparent;background-origin:border-box}
        .heading::before{content:"";position:absolute;top:0;left:0;right:0;height:7px;background:linear-gradient(90deg,#f6ab07,#ffed00)}
        .kicker{display:block;width:fit-content;color:#ffed00;background:linear-gradient(90deg,#f6ab07,#ffed00);background-clip:text;-webkit-background-clip:text;-webkit-text-fill-color:transparent;text-transform:uppercase;letter-spacing:.09em;font-size:12px;font-weight:800;margin-bottom:14px}
        h2{font-size:clamp(25px,5vw,34px);line-height:1.18;margin:0;font-weight:800}
        .photo{position:relative;background:#144c9f}.photo img{display:block;width:100%;height:210px;object-fit:cover;object-position:center 55%}.credit{position:absolute;bottom:7px;right:10px;color:white;background:#0008;border-radius:4px;padding:3px 5px;font-size:9px}.date{display:block;font-size:clamp(29px,6vw,40px);line-height:1.15;font-weight:800;letter-spacing:-.03em;margin:0 0 14px;color:#144c9f}.location{display:block;margin:0 0 18px;font-size:17px;line-height:1.5;font-weight:800;color:#144c9f}.copy{font-size:16px;line-height:1.65;padding:26px 34px 30px}.copy p{padding:0;font-size:inherit;line-height:inherit}.follow{margin-top:14px!important;font-size:14px!important;color:#59667c}.heading h2{font-size:30px}@media(max-width:480px){.photo img{height:155px}.copy{padding:23px 25px}.heading h2{font-size:25px}.date{font-size:30px}}
        p{font-size:18px;line-height:1.65;margin:0;padding:30px 34px 36px}
        strong{color:#164194;font-weight:800}
        button{position:absolute;right:14px;top:20px;display:grid;place-items:center;width:44px;height:44px;border:0;border-radius:50%;background:#ffffff24;color:white;font:32px/1 Arial,sans-serif;cursor:pointer}
        button:hover{background:#ffffff40}button:focus-visible{outline:3px solid #FEDD00;outline-offset:3px}
        @media(max-width:480px){.backdrop{padding:14px}.card{max-height:calc(100dvh - 28px)}.heading{padding:34px 66px 26px 25px}p{padding:25px;font-size:17px}}
      </style>
      <div class="backdrop">
        <section class="card" role="dialog" aria-modal="true" aria-labelledby="title" aria-describedby="copy">
          <div class="heading"><span class="kicker">Save the Date</span><h2 id="title">Regionaltagung 2027</h2></div>
          <div class="photo"><img src="https://www.redbullring.com/de/wp-content/uploads/sites/5/fly-images/55996/TAUROA_SCHOENBERGHOF_SPIELBERG_AUSSEN_NACHT-1-960x9999.jpg" alt="Schönberghof Spielberg am Abend" onerror="this.parentElement.hidden=true"><span class="credit">Bild: TAUROA / Red Bull Ring</span></div>
          <div class="copy" id="copy"><span class="date">02.–03. März 2027</span><span class="location">Hotel Schönberghof Spielberg<br>am Red Bull Ring</span><p>Seid dabei und blockt euch schon heute den Termin für unsere nächste Regionaltagung. Freut euch auf den persönlichen Austausch mit euren Kolleginnen und Kollegen!</p><p class="follow">Weitere Informationen folgen.</p></div>
          <button type="button" aria-label="Hinweis schließen">×</button>
        </section>
      </div>`;
    document.body.appendChild(host);
    const button = root.querySelector('button');
    const focusGuard = event => {
      if (!event.composedPath().includes(host)) button.focus();
    };
    const keyGuard = event => {
      if (event.key === 'Tab') { event.preventDefault(); button.focus(); }
      if (event.key === 'Escape') { event.preventDefault(); event.stopImmediatePropagation(); }
    };
    document.addEventListener('focusin', focusGuard, true);
    document.addEventListener('keydown', keyGuard, true);
    const cleanup = () => {
      document.removeEventListener('focusin', focusGuard, true);
      document.removeEventListener('keydown', keyGuard, true);
      host.remove();
      if (previousFocus && previousFocus.isConnected) previousFocus.focus();
    };
    button.addEventListener('click', () => {
      try { sessionStorage.setItem(key, 'closed'); } catch (_) {}
      cleanup();
    });
    button.focus();
    return cleanup;
  }
  window.defineBlock({
    blockDefinition: {
      name: 'euromaster-nationaltagung-popup',
      factory: BaseBlock => class extends BaseBlock {
        renderBlock(container) {
          if (this.initialized) return;
          this.initialized = true;
          container.style.display = 'none';
          this.cleanupPopup = mount();
        }
        disconnectedCallback() {
          if (this.cleanupPopup) this.cleanupPopup();
          this.initialized = false;
          if (super.disconnectedCallback) super.disconnectedCallback();
        }
        static get observedAttributes() { return []; }
      },
      attributes: [], blockLevel: 'block',
      configurationSchema: {type: 'object', properties: {}}, uiSchema: {},
      label: 'Euromaster Regionaltagung 2027'
    },
    author: 'Euromaster', version: '1.0.0'
  });
})();
